css:
/* Hide theme chrome on this page so it reads like a letter */
.shopify-section-group-header-group,.shopify-section-group-footer-group,#shopify-section-header,#shopify-section-footer,#shopify-section-announcement-bar,.announcement-bar,.announcement-bar-section,.site-header,header.header,.header-wrapper,.site-footer,footer.footer,.breadcrumb,.breadcrumbs,.main-page-title,.page-title,.section-header{display:none !important;}
.page-width--narrow{max-width:none !important;}
body{background:#efe8de !important;}

.mv-adv{--ink:#2a2622;--soft:#5b544c;--mute:#857d73;--line:#e9e1d6;--accent:#8e2f36;--accent-d:#73242a;--tint:#f6ece8;--paper:#faf6f0;--gold:#c9a13b;
  max-width:1060px;margin:0 auto;padding:22px 18px 40px;background:#fff;color:var(--ink);font-family:Georgia,'Times New Roman',serif;font-size:19px;line-height:1.75;-webkit-font-smoothing:antialiased;box-sizing:border-box;}
.mv-adv *,.mv-adv *::before,.mv-adv *::after{box-sizing:border-box;}
.mv-adv p,.mv-adv li{font-size:inherit;line-height:1.75;}
.mv-adv p{margin:0 0 22px;}
.mv-adv a{color:var(--accent);}
.mv-adv h1{font-family:Georgia,serif;font-size:31px;line-height:1.2;margin:10px 0 16px;color:var(--ink);letter-spacing:-0.4px;font-weight:700;}
.mv-adv h2{font-family:Georgia,serif;font-size:25px;line-height:1.3;margin:52px 0 16px;color:var(--ink);font-weight:700;}
.mv-adv .sans{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;}

.mv-adv .ad-label{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:11px;letter-spacing:1.6px;text-transform:uppercase;color:var(--mute);text-align:right;margin:0 0 8px;}
.mv-adv .banner{background:var(--accent);color:#fff;text-align:center;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;font-weight:700;letter-spacing:0.7px;text-transform:uppercase;padding:12px 16px;border-radius:4px;margin:0 0 30px;line-height:1.5;}
.mv-adv .head{text-align:center;margin-bottom:38px;}
.mv-adv .kicker{display:inline-block;background:var(--tint);color:var(--accent);font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;padding:7px 16px;border-radius:4px;margin:4px 0 14px;}
.mv-adv .deck{font-size:19px;font-style:italic;color:var(--soft);line-height:1.55;margin:0 auto 24px;max-width:760px;}
.mv-adv .byline{display:flex;align-items:center;justify-content:center;gap:12px;color:var(--mute);font-size:15px;padding-top:18px;border-top:1px solid var(--line);max-width:700px;margin:22px auto 0;}
.mv-adv .byline img{width:52px;height:52px;border-radius:50%;object-fit:cover;border:2px solid #fff;box-shadow:0 0 0 1px var(--line);}
.mv-adv .byline b{color:var(--ink);font-weight:700;}

.mv-adv p.first::first-letter{font-size:64px;font-weight:700;float:left;line-height:0.86;padding:7px 9px 0 0;color:var(--accent);}

.mv-adv figure{margin:30px auto;max-width:580px;}
.mv-adv figure img,.mv-adv .ph{width:100%;height:auto;display:block;border-radius:6px;}
.mv-adv figcaption{text-align:center;color:var(--mute);font-size:15px;font-style:italic;line-height:1.5;margin-top:10px;padding:0 8px;}
.mv-adv .ph{aspect-ratio:4/5;background:repeating-linear-gradient(135deg,#f4eee6 0 14px,#efe7dc 14px 28px);border:1px dashed #cdbfae;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px;color:#8a7c6b;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:14px;letter-spacing:0.4px;}

.mv-adv .pull{border-left:3px solid var(--accent);padding:6px 0 6px 22px;margin:34px 0;font-style:italic;color:#463f38;font-size:21px;line-height:1.55;}

.mv-adv .point{border-top:1px solid var(--line);padding:30px 0 8px;}
.mv-adv .point-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:12px;}
.mv-adv .num{flex:0 0 32px;width:32px;height:32px;background:var(--accent);color:#fff;border-radius:50%;text-align:center;line-height:32px;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-weight:700;font-size:15px;margin-top:2px;}
.mv-adv .point h3{font-family:Georgia,serif;font-size:23px;line-height:1.3;margin:0;color:var(--ink);font-weight:700;}
.mv-adv .note{background:var(--paper);border-radius:6px;padding:16px 20px 14px;margin:16px 0 6px;border-left:3px solid #e2d3c3;}
.mv-adv .note-lab{display:block;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:var(--accent);margin-bottom:4px;}
.mv-adv .note p{font-style:italic;color:#463f38;font-size:18px;line-height:1.55;margin:0;}

.mv-adv .btn{display:inline-block;background:var(--accent);color:#fff !important;text-decoration:none;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-weight:700;font-size:15px;letter-spacing:0.9px;text-transform:uppercase;padding:17px 34px;border-radius:3px;transition:background .2s ease,transform .2s ease;line-height:1.3;}
.mv-adv .btn:hover{background:var(--accent-d);transform:translateY(-1px);}
.mv-adv .mid{text-align:center;margin:40px 0 10px;}
.mv-adv .mid .sub{display:block;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;color:var(--mute);margin-top:10px;}

.mv-adv .compare{display:flex;gap:14px;flex-wrap:wrap;margin:30px 0;}
.mv-adv .col{flex:1 1 260px;border-radius:8px;padding:24px 20px;text-align:center;}
.mv-adv .col.bad{background:#f7f2ee;}
.mv-adv .col.good{background:var(--tint);box-shadow:inset 0 0 0 1px #ecd6d0;}
.mv-adv .col-head{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:10px;}
.mv-adv .bad .col-head{color:#8a7f74;}
.mv-adv .good .col-head{color:var(--accent);}
.mv-adv .col p{font-size:17px;line-height:1.4;margin:0;padding:11px 0;border-top:1px solid rgba(0,0,0,0.06);}
.mv-adv .col p:first-of-type{border-top:0;}
.mv-adv .bad p{color:#6e665d;}
.mv-adv .good p{color:var(--ink);}

.mv-adv .stats{display:flex;flex-wrap:wrap;gap:12px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:26px 0;margin:40px 0;text-align:center;}
.mv-adv .stat{flex:1 1 30%;min-width:100px;}
.mv-adv .stat .big{font-size:29px;font-weight:700;color:var(--accent);line-height:1.1;}
.mv-adv .stat .lab{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--mute);margin-top:7px;line-height:1.4;}

.mv-adv .sign{font-style:italic;font-size:22px;margin-top:-4px;}

.mv-adv .card{background:#f5efe6;border-radius:8px;padding:30px 22px 26px;margin:50px auto;text-align:center;max-width:560px;}
.mv-adv .card-tag{display:inline-block;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#fff;background:var(--accent);padding:5px 12px;border-radius:30px;margin-bottom:16px;}
.mv-adv .card img{width:100%;max-width:340px;height:auto;border-radius:6px;margin:0 auto 18px;display:block;background:#fff;}
.mv-adv .card h3{font-family:Georgia,serif;font-size:22px;line-height:1.3;margin:0 0 10px;color:var(--ink);text-transform:uppercase;letter-spacing:0.5px;}
.mv-adv .card .price{font-size:30px;margin:0 0 6px;line-height:1.2;}
.mv-adv .card .price s{color:#a0978c;font-size:20px;margin-right:8px;}
.mv-adv .card .price b{color:var(--accent);}
.mv-adv .card .save{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;color:var(--soft);margin:0 0 6px;}
.mv-adv .ticks{list-style:none;padding:0;margin:18px auto;text-align:left;max-width:390px;}
.mv-adv .ticks li{position:relative;padding:5px 0 5px 26px;font-size:16px;line-height:1.5;color:#463f38;}
.mv-adv .ticks li::before{content:'✓';position:absolute;left:0;top:5px;color:var(--accent);font-weight:700;}
.mv-adv .card .btn{display:block;width:100%;margin-top:6px;}
.mv-adv .card .fine{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;color:var(--mute);margin:12px 0 0;line-height:1.5;}

.mv-adv .bio{background:var(--paper);border-radius:8px;padding:22px 20px;margin-top:54px;font-size:16px;line-height:1.6;color:#463f38;display:flex;gap:16px;align-items:flex-start;}
.mv-adv .bio img{width:64px;height:64px;border-radius:50%;object-fit:cover;flex:0 0 64px;}
.mv-adv .bio p{margin:0;}
.mv-adv .bio strong{color:var(--ink);}
.mv-adv .disc{font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:12px;color:#a2998e;line-height:1.55;margin:16px 0 0;text-align:center;}

.mv-adv .progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--accent);z-index:10000;}
.mv-adv .sticky{position:fixed;left:0;right:0;bottom:0;background:#fff;box-shadow:0 -4px 18px rgba(0,0,0,0.09);padding:12px 16px calc(12px + env(safe-area-inset-bottom,0px));z-index:9999;transform:translateY(110%);transition:transform .45s ease;}
.mv-adv .sticky.on{transform:translateY(0);}
.mv-adv .sticky a{display:block;max-width:520px;margin:0 auto;text-align:center;background:var(--accent);color:#fff !important;text-decoration:none;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;font-weight:700;font-size:14px;letter-spacing:0.8px;text-transform:uppercase;padding:15px 18px;border-radius:3px;}

@media (min-width:768px){
  .mv-adv{padding:56px 92px 64px;margin:44px auto;border-radius:10px;box-shadow:0 10px 44px rgba(60,40,20,0.08);font-size:21px;}
  .mv-adv h1{font-size:44px;}
  .mv-adv h2{font-size:31px;}
  .mv-adv .deck{font-size:22px;}
  .mv-adv .point h3{font-size:26px;}
  .mv-adv .note p{font-size:19px;}
  .mv-adv .col p{font-size:18px;}
  .mv-adv .stat .big{font-size:36px;}
  .mv-adv .card{padding:38px 40px 32px;}
  .mv-adv .card .btn{display:inline-block;width:auto;}
}

#shopify-section-bar,
#shopify-section-header,
#shopify-section-footer,
#shopify-section-footer-promotions,
#shopify-section-newsletter-popup,
.shopify-section-group-header-group,
.shopify-section-group-footer-group,
.template-page .section-header,
.breadcrumb,
.breadcrumbs {
  display:none!important;
}
body.template-page,
body.template-page .main-content {
  background:#efe6d9!important;
}
body.template-page {
  padding-bottom:80px!important;
}
.template-page .page-content {
  padding-top:0!important;
}
.lo-antonia-outer {
  background:#efe6d9;
  padding:26px 12px;
  margin:0 -16px;
}
.lo-antonia {
  max-width:600px;
  margin:0 auto;
  background:#fff;
  padding:22px 26px 34px;
  font-family:Georgia,'Times New Roman',serif;
  font-size:17px;
  line-height:1.7;
  color:#2a2622;
}
.lo-antonia * {
  box-sizing:border-box;
}
.lo-antonia p {
  margin:0 0 14px;
}
.lo-antonia img {
  max-width:100%;
  height:auto;
  display:block;
  margin-left:auto;
  margin-right:auto;
}
.lo-antonia h1 {
  font-family:Georgia,'Times New Roman',serif;
  font-size:27px;
  line-height:1.22;
  text-transform:uppercase;
  text-align:center;
  margin:0 0 14px;
  font-weight:bold;
  color:#2a2622;
}
.lo-antonia h2 {
  font-family:Georgia,'Times New Roman',serif;
  font-size:17px;
  font-weight:600;
  letter-spacing:.025em;
  text-transform:uppercase;
  margin:0 0 8px;
  color:#2a2622;
  line-height:1.34;
}
.lo-antonia .lo-rule {
  border-top:1px solid #e6ddd0;
  margin-top:18px;
  padding-top:10px;
}
.lo-antonia .lo-figure {
  margin:20px auto;
  text-align:center;
}
.lo-antonia .lo-figure img {
  width:100%;
  max-width:510px;
}
.lo-antonia .lo-cap {
  font-style:italic;
  font-size:13px;
  line-height:1.55;
  color:#7a6f64;
  margin-top:8px;
  text-align:center;
}
.lo-antonia .lo-note {
  background:#fcf9f5;
  border:1px solid #e6ddd0;
  padding:15px;
  margin:17px 0;
}
.lo-antonia .lo-note-title {
  color:#a8472f;
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase;
  font-weight:bold;
  margin-bottom:7px;
}
.lo-antonia .lo-note p {
  font-style:italic;
  font-size:15px;
  color:#7a6f64;
  margin:0;
}
.lo-antonia .lo-number {
  display:inline-block;
  width:24px;
  height:24px;
  line-height:24px;
  border-radius:50%;
  background:#a8472f;
  color:#fff;
  text-align:center;
  font-size:13px;
  margin-right:8px;
  vertical-align:2px;
}
.lo-antonia .lo-cta {
  text-align:center;
  margin:6px 0 22px;
}
.lo-antonia .lo-btn {
  display:inline-block;
  background:#a8472f;
  color:#fff!important;
  padding:15px 26px;
  text-decoration:none;
  font-family:Georgia,'Times New Roman',serif;
  font-size:15px;
  letter-spacing:.06em;
  text-transform:uppercase;
  line-height:1.35;
}
.lo-antonia .lo-btn:hover {
  background:#8e3926;
}
.lo-antonia .lo-compare {
  display:flex;
  gap:12px;
  margin:20px 0;
  flex-wrap:wrap;
}
.lo-antonia .lo-compare-col {
  flex:1;
  min-width:220px;
  background:#f7f1e8;
  border:1px solid #e6ddd0;
  padding:18px 16px;
  border-radius:3px;
}
.lo-antonia .lo-compare-col.better {
  background:#fff;
  border:2px solid #a8472f;
  box-shadow:0 2px 8px rgba(168,71,47,.06);
}
.lo-antonia .lo-compare-head {
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase;
  font-weight:bold;
  color:#7a6f64;
  margin-bottom:10px;
  text-align:center;
}
.lo-antonia .lo-compare-col.better .lo-compare-head {
  color:#a8472f;
}
.lo-antonia .lo-compare-line {
  font-size:13px;
  line-height:1.6;
  margin-bottom:6px;
}
.lo-antonia .lo-metrics {
  display:flex;
  justify-content:space-around;
  align-items:center;
  gap:5px;
  text-align:center;
  border-top:1px solid #e6ddd0;
  border-bottom:1px solid #e6ddd0;
  padding:18px 0;
  margin:22px 0;
}
.lo-antonia .lo-metric {
  flex:1;
}
.lo-antonia .lo-metric:not(:last-child) {
  border-right:1px solid #e6ddd0;
}
.lo-antonia .lo-metric-main {
  font-size:16px;
  font-weight:bold;
  color:#a8472f;
}
.lo-antonia .lo-metric-lab {
  font-size:10px;
  letter-spacing:.1em;
  text-transform:uppercase;
  color:#7a6f64;
  margin-top:3px;
  line-height:1.4;
}
.lo-antonia .lo-card {
  border:1px solid #a8472f;
  padding:22px 20px;
  margin:10px 0 18px;
  text-align:center;
}
.lo-antonia .lo-card-title {
  font-size:13px;
  letter-spacing:.14em;
  text-transform:uppercase;
  font-weight:bold;
  margin:6px 0;
  color:#2a2622;
}
.lo-antonia .lo-price {
  font-size:16px;
  margin-bottom:14px;
}
.lo-antonia .lo-price strong {
  font-size:20px;
  color:#a8472f;
}
.lo-antonia .lo-price s {
  color:#7a6f64;
  font-size:14px;
  margin-right:5px;
}
.lo-antonia .lo-features {
  text-align:left;
  font-size:14px;
  line-height:1.6;
  max-width:420px;
  margin:0 auto 18px;
}
.lo-antonia .lo-feature {
  margin-bottom:6px;
}
.lo-antonia .lo-feature span {
  color:#a8472f;
  font-weight:bold;
  margin-right:5px;
}
.lo-antonia .lo-footer {
  border-top:1px solid #e6ddd0;
  padding-top:12px;
  font-size:11px;
  line-height:1.6;
  color:#7a6f64;
}
.lo-antonia-sticky {
  position:fixed;
  left:0;
  right:0;
  bottom:0;
  z-index:9999;
  background:#fff;
  border-top:1px solid #e6ddd0;
  box-shadow:0 -4px 14px rgba(0,0,0,.08);
  padding:12px;
  display:flex;
  align-items:center;
  justify-content:center;
  font-family:Georgia,'Times New Roman',serif;
  transform:translateY(110%);
  transition:transform .25s ease;
}
.lo-antonia-sticky.lo-visible {
  transform:translateY(0);
}
.lo-antonia-sticky a {
  background:#a8472f;
  color:#fff!important;
  padding:14px 24px;
  text-decoration:none;
  font-size:13px;
  letter-spacing:.06em;
  text-transform:uppercase;
  font-weight:bold;
  width:100%;
  max-width:400px;
  text-align:center;
  border-radius:3px;
}
@media(max-width:600px) {
  .lo-antonia-outer {
    padding:10px 7px;
    margin:0;
    box-sizing:border-box;
    width:100%;
  }
  .lo-antonia {
    padding:19px 15px 28px;
    font-size:16px;
  }
  .lo-antonia h1 {
    font-size:26px;
  }
  .lo-antonia .lo-compare-col {
    min-width:130px;
    padding:13px 10px;
  }
  .lo-antonia .lo-compare-head {
    font-size:10px;
  }
  .lo-antonia .lo-compare-line {
    font-size:12px;
  }
  .lo-antonia .lo-card {
    padding:18px 13px;
  }
  .lo-antonia .lo-metric-main {
    font-size:15px;
  }
}

.page-width--narrow{max-width:none !important;}
.mb-bleed,.mb-bleed *,.mb-bleed *::before,.mb-bleed *::after,.mb-lp,.mb-lp *,.mb-lp *::before,.mb-lp *::after{box-sizing:border-box !important;}
