.mb-lp{max-width:1160px !important;margin:0 auto !important;padding:24px 18px !important;background:#ffffff !important;color:#2c2a26 !important;font-family:Georgia,'Times New Roman',serif !important;line-height:1.75 !important;font-size:19px !important;}
.mb-lp p,.mb-lp li{font-size:19px !important;line-height:1.75 !important;color:#2c2a26 !important;}
.mb-lp p{margin:0 0 22px !important;}
.mb-lp p::first-letter{font-size:inherit !important;font-weight:inherit !important;line-height:inherit !important;float:none !important;padding:0 !important;margin:0 !important;color:inherit !important;font-family:inherit !important;}
.mb-lp h1{font-family:Georgia,'Times New Roman',serif !important;font-size:34px !important;line-height:1.2 !important;margin:12px 0 14px !important;color:#2c2a26 !important;letter-spacing:-0.3px !important;font-weight:700 !important;text-transform:none !important;}
.mb-lp h2{font-family:Georgia,'Times New Roman',serif !important;font-size:25px !important;line-height:1.3 !important;margin:48px 0 16px !important;color:#2c2a26 !important;font-weight:700 !important;text-transform:none !important;letter-spacing:0 !important;}
.mb-lp .banner{background:#b0532c !important;color:#fff !important;text-align:center !important;font-family:Helvetica,Arial,sans-serif !important;font-size:14px !important;font-weight:700 !important;letter-spacing:0.6px !important;text-transform:uppercase !important;padding:12px 16px !important;border-radius:4px !important;margin:0 0 28px !important;line-height:1.5 !important;}
.mb-lp .head{text-align:center !important;margin-bottom:38px !important;}
.mb-lp .kicker{display:inline-block !important;background:#f6ebe4 !important;color:#b0532c !important;font-family:Helvetica,Arial,sans-serif !important;font-size:12px !important;font-weight:700 !important;letter-spacing:1.5px !important;text-transform:uppercase !important;padding:7px 16px !important;border-radius:4px !important;margin:6px 0 14px !important;}
.mb-lp .deck{font-family:Georgia,'Times New Roman',serif !important;font-size:20px !important;font-style:italic !important;color:#5a544c !important;line-height:1.5 !important;margin:0 0 28px !important;}
.mb-lp .head .deck{max-width:780px !important;margin-left:auto !important;margin-right:auto !important;}
.mb-lp .head-meta{color:#807a72 !important;font-size:15px !important;letter-spacing:0.3px !important;padding-top:18px !important;border-top:1px solid #ebe5dc !important;margin:24px auto 0 !important;max-width:720px !important;display:flex !important;align-items:center !important;justify-content:center !important;gap:12px !important;}
.mb-lp .head-meta img{width:52px !important;height:52px !important;border-radius:50% !important;object-fit:cover !important;margin:0 !important;flex:none !important;}
.mb-lp p.first-para::first-letter{font-family:Georgia,'Times New Roman',serif !important;font-size:60px !important;font-weight:700 !important;float:left !important;line-height:0.9 !important;padding:6px 8px 0 0 !important;color:#b0532c !important;}
.mb-lp img.inline-img{width:100% !important;height:auto !important;display:block !important;margin:24px auto !important;border-radius:6px !important;max-width:560px !important;}
.mb-lp .img-caption{text-align:center !important;color:#807a72 !important;font-size:15px !important;font-style:italic !important;margin-top:-12px !important;margin-bottom:24px !important;}
.mb-lp .pull-quote{border-left:3px solid #b0532c !important;padding:8px 0 8px 22px !important;margin:32px 0 !important;font-style:italic !important;color:#4a4640 !important;font-size:21px !important;line-height:1.55 !important;}
.mb-lp .decision{border-top:1px solid #ebe5dc !important;padding:28px 0 10px !important;}
.mb-lp .decision .dn{display:inline-block !important;width:32px !important;height:32px !important;background:#b0532c !important;color:#fff !important;border-radius:50% !important;text-align:center !important;line-height:32px !important;font-family:Helvetica,Arial,sans-serif !important;font-weight:700 !important;font-size:16px !important;margin-right:10px !important;vertical-align:middle !important;}
.mb-lp .decision h3{display:inline !important;font-family:Georgia,'Times New Roman',serif !important;font-size:24px !important;color:#2c2a26 !important;font-weight:700 !important;text-transform:none !important;letter-spacing:0 !important;}
.mb-lp .decision p{margin:14px 0 !important;}
.mb-lp .testi{background:#faf6ef !important;border-radius:6px !important;padding:18px 20px !important;margin:14px 0 4px !important;}
.mb-lp .testi .stars{color:#d4a72c !important;letter-spacing:2px !important;font-size:16px !important;}
.mb-lp .testi p{font-size:18px !important;font-style:italic !important;color:#4a4640 !important;margin:6px 0 4px !important;line-height:1.5 !important;}
.mb-lp .testi .who{font-style:normal !important;font-size:14px !important;color:#807a72 !important;font-weight:700 !important;}
.mb-lp .compare{display:flex !important;gap:16px !important;margin:34px 0 !important;flex-wrap:wrap !important;}
.mb-lp .compare .col{flex:1 1 240px !important;min-width:240px !important;border-radius:8px !important;padding:24px 20px !important;text-align:center !important;}
.mb-lp .compare .col.bad{background:#fbf0ee !important;}
.mb-lp .compare .col.good{background:#f6ebe4 !important;}
.mb-lp .compare .col-head{font-family:Helvetica,Arial,sans-serif !important;font-size:13px !important;font-weight:700 !important;letter-spacing:1.5px !important;text-transform:uppercase !important;margin-bottom:12px !important;}
.mb-lp .compare .bad .col-head{color:#b4554a !important;}
.mb-lp .compare .good .col-head{color:#b0532c !important;}
.mb-lp .compare .col p{font-size:17px !important;color:#4a4640 !important;margin:12px 0 !important;line-height:1.4 !important;}
.mb-lp .stats{display:flex !important;gap:12px !important;flex-wrap:wrap !important;border-top:1px solid #ebe5dc !important;border-bottom:1px solid #ebe5dc !important;padding:28px 0 !important;margin:40px 0 !important;text-align:center !important;}
.mb-lp .stats .stat{flex:1 1 120px !important;min-width:120px !important;}
.mb-lp .stats .num{font-family:Georgia,'Times New Roman',serif !important;font-size:32px !important;font-weight:700 !important;color:#b0532c !important;line-height:1.1 !important;}
.mb-lp .stats .lab{font-family:Helvetica,Arial,sans-serif !important;font-size:12px !important;letter-spacing:1px !important;text-transform:uppercase !important;color:#807a72 !important;margin-top:6px !important;}
.mb-lp .cta-card{background:#f5efe6 !important;border-radius:6px !important;padding:32px 24px !important;margin:48px auto !important;text-align:center !important;max-width:560px !important;}
.mb-lp .cta-card h3{font-family:Georgia,'Times New Roman',serif !important;font-size:24px !important;margin:0 0 8px !important;color:#2c2a26 !important;font-weight:700 !important;line-height:1.3 !important;}
.mb-lp .cta-card img{width:100% !important;max-width:340px !important;height:auto !important;border-radius:6px !important;margin:0 auto 18px !important;display:block !important;}
.mb-lp .cta-card .stars{color:#d4a72c !important;letter-spacing:2px !important;font-size:17px !important;margin:0 0 10px !important;}
.mb-lp .cta-card .price{font-family:Georgia,'Times New Roman',serif !important;font-size:30px !important;margin:0 0 14px !important;color:#2c2a26 !important;}
.mb-lp .cta-card .price s{color:#9b938a !important;font-size:21px !important;margin-right:9px !important;}
.mb-lp .cta-card .price b{color:#b0532c !important;}
.mb-lp .cta-bullets{list-style:none !important;padding:0 !important;margin:16px auto !important;text-align:left !important;max-width:380px !important;}
.mb-lp .cta-bullets li{padding:4px 0 4px 24px !important;position:relative !important;font-size:16px !important;color:#4a4640 !important;line-height:1.55 !important;margin:0 !important;}
.mb-lp .cta-bullets li:before{content:'\2713' !important;color:#b0532c !important;position:absolute !important;left:0 !important;font-weight:700 !important;}
.mb-lp .cta-button{display:inline-block !important;background:#b0532c !important;color:#fff !important;padding:16px 36px !important;text-decoration:none !important;font-family:Helvetica,Arial,sans-serif !important;font-weight:700 !important;letter-spacing:0.8px !important;border-radius:3px !important;margin:12px 0 4px !important;font-size:16px !important;text-transform:uppercase !important;border:0 !important;}
.mb-lp .cta-note{font-family:Helvetica,Arial,sans-serif !important;font-size:14px !important;color:#8a8178 !important;margin-top:12px !important;}
.mb-lp .mid-cta{text-align:center !important;margin:38px 0 !important;}
.mb-lp .author-bio{background:#faf6ef !important;border-radius:6px !important;padding:24px 22px !important;margin-top:56px !important;font-size:16px !important;line-height:1.6 !important;color:#4a4640 !important;}
.mb-lp .author-bio strong{color:#2c2a26 !important;}
.mb-lp .disclaimer,.mb-lp p.disclaimer{font-size:13px !important;color:#a09a90 !important;font-style:italic !important;margin:16px 0 0 !important;line-height:1.5 !important;}
.nv-sticky{position:fixed !important;bottom:0 !important;left:0 !important;width:100% !important;padding:14px 20px calc(14px + env(safe-area-inset-bottom,0px)) 20px !important;background:#ffffff !important;box-shadow:0 -2px 16px rgba(0,0,0,0.08) !important;z-index:9999 !important;text-align:center !important;box-sizing:border-box !important;}
.nv-sticky-inner{max-width:500px !important;margin:0 auto !important;}
.nv-sticky a.nv-btn{display:block !important;padding:16px 36px !important;background:#b0532c !important;color:#fff !important;font-family:Helvetica,Arial,sans-serif !important;font-size:15px !important;font-weight:700 !important;letter-spacing:0.8px !important;text-transform:uppercase !important;border-radius:3px !important;text-decoration:none !important;text-align:center !important;}
.nv-js .nv-sticky{transform:translateY(100%) !important;opacity:0 !important;transition:transform .5s ease,opacity .4s ease !important;}
.nv-js .nv-sticky.nv-on{transform:translateY(0) !important;opacity:1 !important;}
.nv-progress{position:fixed !important;top:0 !important;left:0 !important;height:3px !important;background:#b0532c !important;z-index:10000 !important;width:0% !important;}
@media(min-width:768px){.mb-lp{padding:64px 96px !important;margin:44px auto !important;border-radius:10px !important;box-shadow:0 8px 40px rgba(0,0,0,0.08) !important;font-size:22px !important;}.mb-lp p,.mb-lp li{font-size:22px !important;}.mb-lp h1{font-size:46px !important;}.mb-lp h2{font-size:31px !important;}.mb-lp .deck{font-size:23px !important;}.mb-lp .decision h3{font-size:26px !important;}.mb-lp .head-meta{font-size:16px !important;}.mb-lp .compare .col p{font-size:18px !important;}.mb-lp .stats .num{font-size:36px !important;}.mb-lp .testi p{font-size:20px !important;}}
